-- Content only: generated by build_muvna_content.mjs. Run after the catalogue import.
-- Existing nonempty fields are preserved. No prices, stock, images or publication changes.
BEGIN;
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '60s';
DO $$ BEGIN
  IF to_regclass('public.accessory_products') IS NULL
     OR to_regclass('public.accessory_variants') IS NULL
     OR to_regclass('public.accessory_translations') IS NULL THEN
    RAISE EXCEPTION 'First run the accessories schema migration and MUVNA catalogue import';
  END IF;
END $$;
CREATE TEMP TABLE muvna_content_payload ON COMMIT DROP AS
SELECT value AS data FROM jsonb_array_elements($muvna_content$__PAYLOAD__$muvna_content$::jsonb);

-- Match exact SKU groups, not editable slugs. Fail atomically if grouping has changed.
CREATE TEMP TABLE muvna_content_targets ON COMMIT DROP AS
SELECT p.id, s.data FROM muvna_content_payload s
JOIN public.accessory_products p ON lower(p.brand) = 'muvna'
AND (SELECT array_agg(v.sku ORDER BY v.sku) FROM public.accessory_variants v WHERE v.product_id=p.id)
  = (SELECT array_agg(x ORDER BY x) FROM jsonb_array_elements_text(s.data->'skus') x);
DO $$ BEGIN
  IF (SELECT count(*) FROM muvna_content_targets) <> 110 THEN
    RAISE EXCEPTION 'MUVNA SKU groups missing or changed: %',
      (SELECT string_agg(s.data->>'slug', ', ') FROM muvna_content_payload s
       WHERE NOT EXISTS (SELECT 1 FROM muvna_content_targets t WHERE t.data->>'slug'=s.data->>'slug'));
  END IF;
END $$;
-- Same parent lock used by the staff editor; timestamps invalidate stale editor forms.
SELECT p.id FROM public.accessory_products p JOIN muvna_content_targets t ON t.id=p.id
ORDER BY p.id FOR UPDATE OF p;
DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM muvna_content_targets t JOIN public.accessory_products p ON p.id=t.id
    WHERE lower(p.brand)<>'muvna' OR
      (SELECT array_agg(v.sku ORDER BY v.sku) FROM public.accessory_variants v WHERE v.product_id=p.id)
      IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM jsonb_array_elements_text(t.data->'skus') x)
  ) THEN RAISE EXCEPTION 'MUVNA SKU groups changed concurrently; retry after checking the catalogue'; END IF;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.muvna_fill_missing(old_value jsonb, new_value jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE k text; v jsonb; result jsonb := old_value;
BEGIN
  IF old_value IS NULL OR old_value='null'::jsonb
     OR (jsonb_typeof(old_value)='string' AND btrim(old_value #>> '{}')='') THEN
    RETURN new_value;
  END IF;
  IF jsonb_typeof(old_value)='object' AND jsonb_typeof(new_value)='object' THEN
    FOR k,v IN SELECT * FROM jsonb_each(new_value) LOOP
      result := jsonb_set(result, ARRAY[k], pg_temp.muvna_fill_missing(result->k,v), true);
    END LOOP;
  END IF;
  RETURN result;
END $$;
CREATE TEMP TABLE muvna_content_changes (id uuid, kind text) ON COMMIT DROP;
WITH changed AS (
  INSERT INTO public.accessory_translations AS existing (product_id,locale,name,description)
  SELECT t.id,(tr->>'locale')::public.locale,tr->>'name',tr->>'description'
  FROM muvna_content_targets t CROSS JOIN LATERAL jsonb_array_elements(t.data->'translations') tr
  ON CONFLICT (product_id,locale) DO UPDATE SET
    name=CASE WHEN btrim(existing.name)='' THEN excluded.name ELSE existing.name END,
    description=CASE WHEN btrim(existing.description)='' THEN excluded.description ELSE existing.description END
  WHERE btrim(existing.name)='' OR btrim(existing.description)=''
  RETURNING product_id
) INSERT INTO muvna_content_changes SELECT product_id,'translation' FROM changed;
WITH changed AS (
  UPDATE public.accessory_products p
  SET attributes=pg_temp.muvna_fill_missing(p.attributes,t.data->'attributes')
  FROM muvna_content_targets t WHERE p.id=t.id
    AND p.attributes IS DISTINCT FROM pg_temp.muvna_fill_missing(p.attributes,t.data->'attributes')
  RETURNING p.id
) INSERT INTO muvna_content_changes SELECT id,'attributes' FROM changed;
UPDATE public.accessory_products SET updated_at=clock_timestamp()
WHERE id IN (SELECT id FROM muvna_content_changes);
SELECT count(*) FILTER (WHERE kind='translation') AS translation_rows_filled,
       count(*) FILTER (WHERE kind='attributes') AS product_attributes_filled,
       count(DISTINCT id) AS products_changed
FROM muvna_content_changes;
COMMIT;
